package com.chronos.integration.model; import com.chronos.model.pojo.BaseEntity; import java.time.LocalDateTime; import jakarta.persistence.*; import lombok.Getter; import lombok.Setter;
@Entity @Table(name="int_dead_letter") @Getter @Setter public class DeadLetter extends BaseEntity { @Column(name="item_error_id",nullable=false,length=64) private String itemErrorId; @Column(name="run_id",nullable=false,length=64) private String runId; @Column(name="replay_count",nullable=false) private int replayCount; @Column(nullable=false,length=20) private String status="PENDING"; @Column(name="last_result",columnDefinition="text") private String lastResult; @Column(name="replayed_at") private LocalDateTime replayedAt; }
